#!/usr/bin/env python3
# Standalone fail-closed exact verifier for lemma L2, finite scope n<=64.
# No imports, no I/O, no network, no filesystem, deterministic, exact integer
# arithmetic only. Entry point verify(witness) raises on any failed check.

def is_prime(k):
    if k < 2:
        return False
    d = 2
    while d * d <= k:
        if k % d == 0:
            return False
        d += 1
    return True

def phi(m):
    result = 1
    mm = m
    d = 2
    while d * d <= mm:
        if mm % d == 0:
            pk = 1
            while mm % d == 0:
                mm //= d
                pk *= d
            result *= pk - pk // d
        d += 1
    if mm > 1:
        result *= mm - 1
    return result

def p_n(n):
    # smallest prime congruent to 1 mod n, fail-closed search bound
    k = 1
    while True:
        cand = k * n + 1
        if cand > 10000000:
            raise AssertionError("p_n bound exceeded at n=%d" % n)
        if is_prime(cand):
            return cand
        k += 1

def m_n(n, bound):
    # smallest m with n | phi(m), exhaustive from m=1, fail-closed
    for m in range(1, bound + 1):
        if phi(m) % n == 0:
            return m
    raise AssertionError("m_n bound exceeded at n=%d" % n)

def verify(witness):
    n_values = witness["n_values"]
    expected = witness["expected"]
    seen = []
    for entry in expected:
        n = entry["n"]
        if n not in n_values:
            raise AssertionError("entry n=%d not in n_values" % n)
        if n in seen:
            raise AssertionError("duplicate entry n=%d" % n)
        seen.append(n)
        p = p_n(n)
        if p != entry["p"]:
            raise AssertionError("p_n mismatch at n=%d" % n)
        m = m_n(n, p)
        if m != entry["m"]:
            raise AssertionError("m_n mismatch at n=%d" % n)
        if (m < p) != entry["m_lt_p"]:
            raise AssertionError("strict inequality verdict mismatch at n=%d" % n)
    if sorted(seen) != sorted(n_values):
        raise AssertionError("entry set does not match n_values")
